diff --git a/internal/command/registry.go b/internal/command/registry.go
new file mode 100644
index 0000000..0fd86d0
--- /dev/null
+++ b/internal/command/registry.go
@@ -0,0 +1,118 @@
+package command
+
+// EntryKind says whether an entry opens a view or runs an action.
+type EntryKind int
+
+const (
+	KindView EntryKind = iota
+	KindAction
+)
+
+// MaxDescriptionLen is the longest description, in runes.
+const MaxDescriptionLen = 45
+
+// Entry is one command target with all its spellings.
+type Entry struct {
+	Name        string
+	Aliases     []string
+	Description string
+	// Arg is the argument placeholder an action takes, e.g. "<name>"; empty
+	// when the entry takes none.
+	Arg  string
+	Kind EntryKind
+}
+
+// Label is what a listing shows for the entry: the name, followed by its
+// argument placeholder when it takes one.
+func (e Entry) Label() string {
+	if e.Arg == "" {
+		return e.Name
+	}
+	return e.Name + " " + e.Arg
+}
+
+// TakesArg reports whether the entry expects an argument.
+func (e Entry) TakesArg() bool { return e.Arg != "" }
+
+// spec is a registry row: the public Entry plus what the parser resolves it to.
+type spec struct {
+	Entry
+	view   ViewType    // KindView only
+	action CommandType // KindAction only
+}
+
+// registry is the single source of every command spelling: parsing
+// (viewNames, actionNames, actionAliases), completion and listings all derive
+// from it. Views come first, then actions, each alphabetical by canonical name;
+// aliases keep their declaration order. ViewViewer is deliberately absent, for
+// the reason given on its declaration.
+var registry = []spec{
+	{Entry{Name: "about", Aliases: []string{"version"}, Description: "Build version and where files are kept"}, ViewAbout, ""},
+	{Entry{Name: "agent-usage", Aliases: []string{"au"}, Description: "Claude Code sessions and token usage"}, ViewAgentUsage, ""},
+	{Entry{Name: "configuration", Aliases: []string{"config", "cfg"}, Description: "Settings of the current context"}, ViewConfiguration, ""},
+	{Entry{Name: "containers", Aliases: []string{"cont", "ct"}, Description: "Containers, metrics and logs"}, ViewContainers, ""},
+	{Entry{Name: "dashboard", Aliases: []string{"dash", "d"}, Description: "Code, health, host and Docker at a glance"}, ViewDashboard, ""},
+	{Entry{Name: "files", Aliases: []string{"fs"}, Description: "Browse the whole filesystem"}, ViewFiles, ""},
+	{Entry{Name: "git-auth", Aliases: []string{"ga"}, Description: "Sign in to your forge"}, ViewGitAuth, ""},
+	{Entry{Name: "git-explorer", Aliases: []string{"ge"}, Description: "Browse and clone forge projects"}, ViewGitExplorer, ""},
+	{Entry{Name: "jobs", Aliases: []string{"j"}, Description: "Scans, syncs and pulls of this session"}, ViewJobs, ""},
+	{Entry{Name: "netdiag", Aliases: []string{"net"}, Description: "Reachability, ports, interfaces, forwarding"}, ViewNetdiag, ""},
+	{Entry{Name: "oci-resources", Aliases: []string{"oci"}, Description: "Images, networks, volumes and registries"}, ViewOCIResources, ""},
+	{Entry{Name: "security", Aliases: []string{"sec"}, Description: "CVE, secret and license scans"}, ViewSecurity, ""},
+	{Entry{Name: "status", Aliases: []string{"s"}, Description: "HTTP, ICMP, DNS and SSL checks"}, ViewStatus, ""},
+	{Entry{Name: "templates", Aliases: []string{"tpl"}, Description: "Repository template catalog"}, ViewTemplates, ""},
+	{Entry{Name: "workspaces", Aliases: []string{"ws", "w"}, Description: "Local repositories and their Git state"}, ViewWorkspaces, ""},
+	{Entry{Name: "context", Aliases: []string{"ctx", "c"}, Description: "Switch or list contexts", Arg: "<name>", Kind: KindAction}, "", CommandContext},
+	{Entry{Name: "quit", Aliases: []string{"q"}, Description: "Exit DevDesk", Kind: KindAction}, "", CommandQuit},
+}
+
+// Entries returns the ordered registry as a deep copy: callers may modify it
+// freely.
+func Entries() []Entry {
+	out := make([]Entry, len(registry))
+	for i, s := range registry {
+		out[i] = s.Entry
+		out[i].Aliases = append([]string(nil), s.Aliases...)
+	}
+	return out
+}
+
+// buildViewNames derives the spelling-to-view map from the registry.
+func buildViewNames() map[string]ViewType {
+	m := make(map[string]ViewType)
+	for _, s := range registry {
+		if s.Kind != KindView {
+			continue
+		}
+		m[s.Name] = s.view
+		for _, a := range s.Aliases {
+			m[a] = s.view
+		}
+	}
+	return m
+}
+
+// buildActionNames derives the action-name map from the registry.
+func buildActionNames() map[string]CommandType {
+	m := make(map[string]CommandType)
+	for _, s := range registry {
+		if s.Kind == KindAction {
+			m[s.Name] = s.action
+		}
+	}
+	return m
+}
+
+// buildActionAliases derives the action alias-to-name map from the registry.
+func buildActionAliases() map[string]string {
+	m := make(map[string]string)
+	for _, s := range registry {
+		if s.Kind != KindAction {
+			continue
+		}
+		for _, a := range s.Aliases {
+			m[a] = s.Name
+		}
+	}
+	return m
+}
diff --git a/internal/command/registry_test.go b/internal/command/registry_test.go
new file mode 100644
index 0000000..cc8dd75
--- /dev/null
+++ b/internal/command/registry_test.go
@@ -0,0 +1,218 @@
+package command
+
+import (
+	"reflect"
+	"slices"
+	"testing"
+	"unicode/utf8"
+)
+
+// wantEntries is the expected registry: views A-Z, then actions A-Z, aliases
+// in declaration order.
+var wantEntries = []struct {
+	name    string
+	aliases []string
+	kind    EntryKind
+	arg     string
+}{
+	{"about", []string{"version"}, KindView, ""},
+	{"agent-usage", []string{"au"}, KindView, ""},
+	{"configuration", []string{"config", "cfg"}, KindView, ""},
+	{"containers", []string{"cont", "ct"}, KindView, ""},
+	{"dashboard", []string{"dash", "d"}, KindView, ""},
+	{"files", []string{"fs"}, KindView, ""},
+	{"git-auth", []string{"ga"}, KindView, ""},
+	{"git-explorer", []string{"ge"}, KindView, ""},
+	{"jobs", []string{"j"}, KindView, ""},
+	{"netdiag", []string{"net"}, KindView, ""},
+	{"oci-resources", []string{"oci"}, KindView, ""},
+	{"security", []string{"sec"}, KindView, ""},
+	{"status", []string{"s"}, KindView, ""},
+	{"templates", []string{"tpl"}, KindView, ""},
+	{"workspaces", []string{"ws", "w"}, KindView, ""},
+	{"context", []string{"ctx", "c"}, KindAction, "<name>"},
+	{"quit", []string{"q"}, KindAction, ""},
+}
+
+func TestEntriesMatchExpectedRegistry(t *testing.T) {
+	got := Entries()
+	if len(got) != len(wantEntries) {
+		t.Fatalf("len(Entries()) = %d, want %d", len(got), len(wantEntries))
+	}
+	for i, w := range wantEntries {
+		e := got[i]
+		if e.Name != w.name {
+			t.Errorf("entry %d Name = %q, want %q", i, e.Name, w.name)
+		}
+		if !slices.Equal(e.Aliases, w.aliases) {
+			t.Errorf("%s Aliases = %v, want %v", w.name, e.Aliases, w.aliases)
+		}
+		if e.Kind != w.kind {
+			t.Errorf("%s Kind = %v, want %v", w.name, e.Kind, w.kind)
+		}
+		if e.Arg != w.arg {
+			t.Errorf("%s Arg = %q, want %q", w.name, e.Arg, w.arg)
+		}
+	}
+}
+
+func TestEntriesOrderViewsThenActionsAlphabetical(t *testing.T) {
+	var views, actions []string
+	seenAction := false
+	for _, e := range Entries() {
+		if e.Kind == KindAction {
+			seenAction = true
+			actions = append(actions, e.Name)
+			continue
+		}
+		if seenAction {
+			t.Errorf("view %q after an action", e.Name)
+		}
+		views = append(views, e.Name)
+	}
+	if len(views) == 0 || len(actions) == 0 {
+		t.Fatalf("views=%d actions=%d, want both non-empty", len(views), len(actions))
+	}
+	if !slices.IsSorted(views) {
+		t.Errorf("views not sorted: %v", views)
+	}
+	if !slices.IsSorted(actions) {
+		t.Errorf("actions not sorted: %v", actions)
+	}
+}
+
+func entryNames() []string {
+	var names []string
+	for _, e := range Entries() {
+		names = append(names, e.Name)
+	}
+	return names
+}
+
+func TestEntryNamesEqualFullNames(t *testing.T) {
+	got, want := entryNames(), FullNames()
+	if len(got) == 0 || !slices.Equal(got, want) {
+		t.Errorf("Entries names = %v, FullNames() = %v", got, want)
+	}
+}
+
+func TestFullNamesIsDeterministic(t *testing.T) {
+	first := FullNames()
+	for i := 0; i < 20; i++ {
+		if next := FullNames(); !slices.Equal(first, next) {
+			t.Fatalf("FullNames() order changed: %v vs %v", first, next)
+		}
+	}
+}
+
+func TestEveryAliasIsInExactlyOneEntryOfItsTarget(t *testing.T) {
+	entries := Entries()
+	if len(entries) == 0 {
+		t.Fatal("Entries() is empty")
+	}
+	for alias, target := range GetAliases() {
+		var owners []string
+		for _, e := range entries {
+			if slices.Contains(e.Aliases, alias) {
+				owners = append(owners, e.Name)
+			}
+		}
+		if len(owners) != 1 || owners[0] != target {
+			t.Errorf("alias %q (target %q) found in entries %v", alias, target, owners)
+		}
+	}
+	total := 0
+	for _, e := range entries {
+		total += len(e.Aliases)
+	}
+	if total != len(GetAliases()) {
+		t.Errorf("entries carry %d aliases, GetAliases() has %d", total, len(GetAliases()))
+	}
+}
+
+func TestEntriesAreStableAcrossCalls(t *testing.T) {
+	first := Entries()
+	if len(first) == 0 {
+		t.Fatal("Entries() is empty")
+	}
+	for i := 0; i < 20; i++ {
+		if next := Entries(); !reflect.DeepEqual(first, next) {
+			t.Fatalf("Entries() changed between calls")
+		}
+	}
+}
+
+func TestEveryDescriptionIsNonEmptyAndShort(t *testing.T) {
+	entries := Entries()
+	if len(entries) == 0 {
+		t.Fatal("Entries() is empty")
+	}
+	for _, e := range entries {
+		n := utf8.RuneCountInString(e.Description)
+		if n == 0 {
+			t.Errorf("%s has an empty description", e.Name)
+		}
+		if n > MaxDescriptionLen {
+			t.Errorf("%s description is %d runes, max %d", e.Name, n, MaxDescriptionLen)
+		}
+	}
+}
+
+func TestContextTakesAnArgument(t *testing.T) {
+	var ctx *Entry
+	for _, e := range Entries() {
+		if e.Name == "context" {
+			ctx = &e
+		}
+	}
+	if ctx == nil {
+		t.Fatal("no context entry")
+	}
+	if !ctx.TakesArg() {
+		t.Error("context.TakesArg() = false, want true")
+	}
+	if got := ctx.Label(); got != "context <name>" {
+		t.Errorf("Label() = %q, want %q", got, "context <name>")
+	}
+}
+
+func TestEntriesWithoutArgUseNameAsLabel(t *testing.T) {
+	entries := Entries()
+	if len(entries) == 0 {
+		t.Fatal("Entries() is empty")
+	}
+	for _, e := range entries {
+		if e.Name == "context" {
+			continue
+		}
+		if e.TakesArg() {
+			t.Errorf("%s.TakesArg() = true, want false", e.Name)
+		}
+		if e.Label() != e.Name {
+			t.Errorf("%s.Label() = %q, want %q", e.Name, e.Label(), e.Name)
+		}
+	}
+}
+
+func TestEntriesReturnsACopy(t *testing.T) {
+	a := Entries()
+	if len(a) == 0 {
+		t.Fatal("Entries() is empty")
+	}
+	wantName, wantAlias := a[0].Name, ""
+	if len(a[0].Aliases) > 0 {
+		wantAlias = a[0].Aliases[0]
+	}
+	a[0].Name = "mutated"
+	if len(a[0].Aliases) > 0 {
+		a[0].Aliases[0] = "mutated"
+	}
+	a[0], a[len(a)-1] = a[len(a)-1], a[0]
+	b := Entries()
+	if b[0].Name != wantName {
+		t.Errorf("mutation leaked: first Name = %q, want %q", b[0].Name, wantName)
+	}
+	if wantAlias != "" && b[0].Aliases[0] != wantAlias {
+		t.Errorf("alias mutation leaked: %q, want %q", b[0].Aliases[0], wantAlias)
+	}
+}

tools.description:
Collections grouping workspace pages.

Actions:
  list (no required params);
  retrieve (collection_id);
  create (name; optional access) -- access is fixed at creation and cannot be changed afterwards;
  update (collection_id; optional name, sort_order) -- only the fields you pass are changed;
  delete (collection_id; optional archive_pages) -- the pages survive; archive_pages defaults to true, pass false to leave them unfiled instead;
  list_pages (collection_id; optional search, parent_id, cursor, per_page);
  search_pages (collection_id; optional search) -- pages not yet in this collection, to pick ids for add_pages;
  add_pages (collection_id, page_ids) -- files existing pages; use page create to make new ones;
  remove_page (collection_id, page_collection_id) -- page_collection_id is the membership id from list_pages, not the page id; the page itself is kept;
  list_members (collection_id);
  add_member (collection_id, user_id, member_access);
  update_member (collection_id, collection_member_id, member_access);
  remove_member (collection_id, collection_member_id) -- collection_member_id is the membership id from list_members, not the user id.

access is one of: public, private -- a private collection is visible only to its members, and the level cannot be changed once the collection exists. member_access is one of: view, comment, edit and is a separate scale from access. Collections group workspace pages only; a project's pages cannot be filed in one. To file or move a page, use `page set_collection` -- it works out which collection holds the page for you, so it needs no membership id.

